int sc_pkcs15emu_add_data_object(sc_pkcs15_card_t *p15card,
        const sc_pkcs15_object_t *obj, const sc_pkcs15_data_info_t *data)
{
        return sc_pkcs15emu_object_add(p15card, SC_PKCS15_TYPE_DATA_OBJECT, obj, data);
